<script lang="ts">
/**
 * The explanation itself (DOCB-14569) — shared by the "Show" dialog and the
 * full page: the answer first, the four steps, raw → configured columns,
 * what to do, the KI-Advisor block, the pipeline lane, the run, one line per
 * column in play, and the three notes. Nothing here composes a sentence:
 * every text arrives from the API in DE and EN, this component only picks
 * the reader's language.
 */
import { computed, defineComponent, inject, type PropType } from 'vue';
import { useTolgee } from '@tolgee/vue';
import PipelineFlow from 'src/pages/TouchlessIntelligence/components/PipelineFlow.vue';
import type {
  PipelineStage,
  PipelineText,
} from 'src/services/analytics/PipelineExplanationService';
import type {
  TableExplanation,
  TableExplanationAdvice,
  TableExplanationCall,
  TableExplanationColumn,
  TableExplanationStructuredOutput,
} from 'src/services/analytics/TableExplanationService';

export default defineComponent({
  name: 'AITableExplanationContent',
  components: { PipelineFlow },
  props: {
    explanation: {
      type: Object as PropType<TableExplanation>,
      required: true,
    },
    /** The full pipeline stages (from `pipeline-explanation`), when loaded. */
    stages: { type: Array as PropType<PipelineStage[]>, default: () => [] },
    /** The KI-Advisor block (Nexus), loaded by the parent in a second request. */
    advice: {
      type: Object as PropType<TableExplanationAdvice | null>,
      default: null,
    },
    adviceLoading: { type: Boolean, default: false },
  },
  setup() {
    const tolgee = inject('tolgeeContext', null)
      ? useTolgee(['language'])
      : null;
    const uiLanguage = computed(() => tolgee?.value?.getLanguage() || '');
    return { uiLanguage };
  },
  computed: {
    locale(): string {
      const raw = String(this.uiLanguage || this.$i18n?.locale || 'en');
      return raw.split('-')[0] || 'en';
    },
    pipelineStages(): PipelineStage[] {
      return this.stages.length ? this.stages : [];
    },
    /** Structured output at a glance — from the run's evidence, not the preference. */
    structuredOutput(): TableExplanationStructuredOutput | null {
      return this.explanation?.steps?.extraction?.structured_output || null;
    },
    /** Raw columns the AI found on the document, with their destination. */
    rawColumns(): TableExplanationColumn[] {
      return (this.explanation?.columns || []).filter(
        (c) => c.basis && c.raw_key,
      );
    },
    /** Configured columns in reading order: filled, missing, AI off, hidden. */
    orderedColumns(): TableExplanationColumn[] {
      const columns = this.explanation?.columns || [];
      const order = ['filled', 'missing', 'off', 'hidden'];
      return order.flatMap((state) =>
        columns.filter((c) => this.columnState(c) === state),
      );
    },
    /** Columns the reader cares about: requested from the AI or required. */
    columnsInPlay(): TableExplanationColumn[] {
      return (this.explanation?.columns || []).filter(
        (c) => c.requested_from_ai || c.required || c.state !== 'empty',
      );
    },
  },
  methods: {
    columnState(
      column: TableExplanationColumn,
    ): 'filled' | 'missing' | 'off' | 'hidden' {
      if (column.hidden || column.hidden_by) return 'hidden';
      if (
        (column.state === 'filled' || column.state === 'partial') &&
        column.basis
      )
        return 'filled';
      if (column.requested_from_ai) return 'missing';
      return 'off';
    },
    stateText(column: TableExplanationColumn): string {
      const state = this.columnState(column);
      if (state === 'filled')
        return `${column.filled_rows}/${column.row_count} ${this.$t('ai_explain_rows')}`;
      if (state === 'missing') return this.$t('ai_explain_not_found');
      if (state === 'hidden') return this.$t('ai_explain_hidden');
      // never told either way is not "switched off" — it was simply not set up
      if (column.use_ai === false) return this.$t('ai_explain_ai_off');
      return this.$t('ai_explain_not_configured');
    },
    prettyRaw(column: TableExplanationColumn): string {
      const key =
        String(column.raw_key || column.raw_name || '')
          .split('.')
          .pop() || '';
      return key.replace(/_/g, ' ').replace(/\b\w/g, (ch) => ch.toUpperCase());
    },
    text(value: PipelineText | null | undefined): string {
      if (!value) return '';
      return (
        (this.locale === 'de' ? value.de : value.en) ||
        value.en ||
        value.de ||
        ''
      );
    },
    /**
     * The AI as the reader knows it: Fast / Full / Nexus plus who chose it —
     * never a vendor model id (DOCB-14569: "model bitte immer nur Fast, Full
     * oder Nexus").
     */
    tierText(explanation: TableExplanation): string {
      const tier =
        explanation.steps?.extraction?.tier ||
        explanation.run?.tier ||
        explanation.configuration?.model_selection?.tier ||
        this.$t('ai_explain_tier_unknown');
      const source = this.text(
        explanation.steps?.extraction?.tier_source_label ||
          explanation.configuration?.model_selection?.label,
      );
      return source ? `${tier} — ${source}` : String(tier);
    },
    /** The tier the API resolved for that call — never re-derived from a vendor id here. */
    callTier(call: TableExplanationCall): string {
      return call.tier || this.$t('ai_explain_tier_unknown');
    },
    checkText(valid: boolean | null | undefined): string {
      if (valid === true) return this.$t('ai_explain_check_passed');
      if (valid === false) return this.$t('ai_explain_check_failed');
      return this.$t('ai_explain_check_not_performed');
    },
    when(value: string | null | undefined): string {
      return value ? String(value).replace('T', ' ').slice(0, 19) : '—';
    },
  },
});
</script>

